const faqs = [
  {
    "q": "What is SaaS churn analysis?",
    "a": "SaaS churn analysis evaluates customer attrition rates, MRR impact, and retention patterns to assess business health and predict revenue risk."
  },
  {
    "q": "How is churn rate calculated?",
    "a": "Churn rate = (customers lost in period / customers at start of period) \u00d7 100. For MRR churn, replace customers with MRR values."
  },
  {
    "q": "What is a good NRR for SaaS?",
    "a": "NRR above 100% means expansion revenue exceeds churn. Top-tier SaaS companies target 110-130% NRR. Below 90% indicates serious retention issues."
  }
];

export default function handler(req, res) {
  // CORS
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
  
  if (req.method === 'OPTIONS') {
    return res.status(200).end();
  }
  
  if (req.method === 'GET') {
    // Agent card is a constant — let the edge answer discovery crawls.
    res.setHeader('Cache-Control', 'public, max-age=0, s-maxage=86400, stale-while-revalidate=604800');
    return res.json(agentCard);
  }

  if (req.method === 'POST') {
    const { method, params, id } = req.body || {};

    // JSON-RPC routing
    if (method === 'rpc.discover' || method === 'agent/card') {
      return res.json({ jsonrpc: '2.0', id, result: agentCard });
    }

    if (method === 'faq.search') {
      const query = (params?.query || '').toLowerCase().trim();
      // An empty query previously matched every FAQ, because ''.includes('')
      // is true — a "search" that silently returns the whole corpus.
      const matches = query
        ? faqs.filter(f => f.q.toLowerCase().includes(query) || f.a.toLowerCase().includes(query))
        : [];
      return res.json({ jsonrpc: '2.0', id, result: { query, count: matches.length, faqs: matches } });
    }

    // Discovery convenience: an absent method returns the skills summary. A
    // method that was actually asked for and is not implemented must be a
    // JSON-RPC error, not a success payload the caller has to guess about.
    if (method) {
      return res.json({
        jsonrpc: '2.0', id,
        error: {
          code: -32601,
          message: `Method not found: ${method}`,
          data: { supported: ['rpc.discover', 'agent/card', 'faq.search'] }
        }
      });
    }

    return res.json({
      jsonrpc: '2.0',
      id,
      result: {
        agent: agentCard.name,
        description: agentCard.description,
        skills: agentCard.skills.map(s => ({ id: s.id, name: s.name, description: s.description })),
        faqs: faqs.length
      }
    });
  }
  
  return res.status(405).json({ error: 'Method not allowed' });
}
